{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "In dogs, menaquinone-4 (MK-4), a close quinone-prenyl analogue (Morgan 0.6591), had an absolute oral bioavailability of only 13.5% of IV AUC even with a soft-capsule formulation in non-fasted conditions, directly supporting F <20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "MK-4 absorption was almost absent without bile because mixed micelles are not formed, demonstrating that this lipophilic quinone class depends on bile for solubilization; the query's even longer polyprenyl chain faces the same absorption barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Tocotrienol, a chromanol with a polyprenyl side chain, was reported to have poor oral bioavailability in humans, supporting low F for the query's polyprenyl lipid architecture.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Lycopene, a highly lipophilic C40 isoprenoid, showed very low systemic availability (0.17%) in humans, supporting low F for large lipophilic isoprenoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Phytoene, a C40 isoprenoid, showed 58.5% absolute bioavailability in humans, a high value for a lipophilic isoprenoid, but its lack of the polar quinone head and lower similarity (0.3902) reduce transferability; this is a contradictory signal.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "In a controlled human study, all-trans lycopene bioavailability was 23.2% ±8%, above the threshold, but lycopene estimates vary widely and its similarity to the query is lower; this is a contradictory signal.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C27"],
      "claim": "MK-7 was reported to have superior bioavailability relative to vitamin K1 due to its extended isoprenoid chain and slower clearance, but this is a relative comparison and does not establish an absolute F ≥20%; it is a weak contradictory signal.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hyperforin, a lipophilic prenylated natural product, showed high oral bioavailability in volunteers, but its lower similarity (0.25) and different scaffold limit transferability; this is a weak contradictory signal.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is CoQ10, an extremely lipophilic decaprenyl quinone. The closest structural evidence—menaquinone-4 absolute oral bioavailability of 13.5% in dogs and its near-absent absorption without bile—supports F <20%. Longer-chain MK-7 relative superiority and phytoene's high human F are contradictory but do not establish an absolute F ≥20% for the query. Physicochemical liabilities (MW ~863, extreme logP, no ionizable groups, bile-dependent solubilization) reinforce the low prediction.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for CoQ10 itself or a decaprenyl quinone analogue in humans.",
    "MK-4 absolute bioavailability was measured in dogs; human absolute F may differ.",
    "Formulation and food effects are large for this class; the prediction is for intrinsic molecular bioavailability, not a specific optimized formulation.",
    "The MK-7 relative superiority result does not quantify absolute F, leaving uncertainty about chain-length effects."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C31", "C28", "C37", "C32", "C33", "C36", "C30", "C38", "C34", "C35", "C29"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "menaquinone-4"
    },
    {
      "applicability": "high",
      "card_ids": ["C27"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "menaquinone-7"
    }
  ],
  "revision_action": "strengthen"
}

